function oneSlipMirror(text) {
  const pal = (s) => s === [...s].reverse().join('');
  if (pal(text)) return true;
  for (let k = 0; k < text.length; k++) if (pal(text.slice(0, k) + text.slice(k + 1))) return true;
  return false;
}

function oneSlipMirror(text) {
  const pal = (i, j) => {
    while (i < j) if (text[i++] !== text[j--]) return false;
    return true;
  };
  let i = 0, j = text.length - 1;
  while (i < j) {
    if (text[i] !== text[j]) return pal(i + 1, j) || pal(i, j - 1);
    i++;
    j--;
  }
  return true;
}
